addEventListener('DOMContentLoaded',()=>{const b=document.createElement('button');b.className='btn secondary';b.textContent='Kapacita zakázek';document.querySelector('.top-actions')?.append(b);b.onclick=()=>{const d=document.createElement('dialog');d.innerHTML='<h2>Kontrola kapacity</h2><p>Délka je společný odhad pro všechny zakázky. Kontrola upozorňuje, neblokuje rezervace.</p><label>Datum <input type="date" name="date"></label><label>Minut na zakázku <input type="number" name="duration" value="90" min="15" max="720"></label><label>Počet souběžných míst <input type="number" name="capacity" value="2" min="1" max="20"></label><button data-check>Zkontrolovat</button><button data-close>Zavřít</button><pre role="status"></pre>';document.body.append(d);d.showModal();d.querySelector('[data-close]').onclick=()=>d.remove();d.querySelector('[data-check]').onclick=()=>{const status=d.querySelector('pre'),token=window.PerfectStorage62?.session.getItem('perfectAuthToken');status.textContent='Kontroluji…';google.script.run.withSuccessHandler(r=>{status.textContent=r.conflicts.length?r.conflicts.map(c=>c.time+' — '+c.count+' zakázek: '+c.orders.join(', ')).join('\n'):'Bez překročení kapacity pro zadaný odhad.';if(r.unknown.length)status.textContent+='\nNeznámý čas: '+r.unknown.join(', ');}).withFailureHandler(e=>status.textContent=e.message).perfectCapacity106(token,{date:d.querySelector('[name=date]').value,duration:+d.querySelector('[name=duration]').value,capacity:+d.querySelector('[name=capacity]').value})};};});
(()=>{
 const labels={enabled:'Povolit oznámení mého účtu',assigned:'Přiřazená zakázka',shared:'Společná zakázka',changed:'Změna zakázky nebo směny',revenue:'Denní tržba mého boxu',earnings:'Můj výdělek, bonusy a srážky',details:'Podrobnosti a částky v oznámení'};
 const token=()=>window.PerfectStorage62?.session.getItem('perfectAuthToken')||'';
 async function post(path,value={}){const r=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:token(),...value}),signal:AbortSignal.timeout(15000)});const v=await r.json();if(!r.ok||v.success===false)throw Error(v.message||'Operace nebyla potvrzena.');return v;}
 const ready=()=>Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Služba oznámení se nespustila. Obnov aplikaci.')),10000))]);
 window.perfectNotificationSettings106=async()=>{
 const d=document.createElement('dialog');d.className='p101-dialog';d.innerHTML='<h2>Moje oznámení</h2><p>Na iPhonu otevři aplikaci z ikony na ploše. Náhledy na zamčené obrazovce řídí také nastavení zařízení.</p><form></form><p role="status">Načítám…</p><div class="form-actions"><button class="btn" data-on disabled>Zapnout na tomto zařízení</button><button class="btn secondary" data-off disabled>Vypnout na tomto zařízení</button><button class="btn secondary" data-test disabled>Test doručení</button><button class="btn secondary" data-close>Zavřít</button></div>';document.body.append(d);d.showModal();d.querySelector('[data-close]').onclick=()=>d.remove();const status=d.querySelector('[role=status]');let config;
 try{if(!token())throw Error('Nejdřív se přihlas.');config=await fetch('/push-config',{cache:'no-store'}).then(r=>r.json());if(!config.enabled)throw Error(config.reason||'Server oznámení není nastaven.');const v=(await post('/push-preferences')).preferences;
 for(const [k,label]of Object.entries(labels)){const line=document.createElement('label');line.style.cssText='display:block;padding:10px';const input=document.createElement('input');input.type='checkbox';input.name=k;input.checked=v[k];line.append(input,document.createTextNode(' '+label));d.querySelector('form').append(line);}
 const save=document.createElement('button');save.textContent='Uložit volby';save.className='btn';d.querySelector('form').append(save);d.querySelector('form').onsubmit=async e=>{e.preventDefault();save.disabled=true;try{await post('/push-preferences',{preferences:Object.fromEntries([...d.querySelectorAll('input')].map(i=>[i.name,i.checked]))});status.textContent='Volby uloženy. Pro první aktivaci použij Zapnout na tomto zařízení.';}catch(e){status.textContent=e.message;}finally{save.disabled=false;}};
 if(!('Notification'in window)||!('PushManager'in window)||!('serviceWorker'in navigator))throw Error('Tento režim prohlížeče nepodporuje oznámení. Na iPhonu přidej aplikaci na plochu a otevři ji odtud.');
 d.querySelectorAll('[data-on],[data-off],[data-test]').forEach(b=>b.disabled=false);const reg=await ready(),sub=await reg.pushManager.getSubscription();status.textContent=Notification.permission==='denied'?'Oznámení blokuje prohlížeč. Povol je v oprávněních tohoto webu.':sub&&v.enabled?'Toto zařízení má odběr oznámení.':'Oznámení na tomto zařízení zatím nejsou zapnutá.';
 }catch(e){status.textContent=e.message;}
 const action=fn=>async()=>{const controls=[...d.querySelectorAll('[data-on],[data-off],[data-test]')];controls.forEach(b=>b.disabled=true);try{await fn();}catch(e){status.textContent=e.message;}finally{controls.forEach(b=>b.disabled=false);}};
 d.querySelector('[data-on]').onclick=action(async()=>{
 // Permission request stays directly in the user's click, before network awaits.
 const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Oznámení nebyla povolena. Povol je v nastavení tohoto webu.');const reg=await ready();const raw=atob(config.publicKey.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-config.publicKey.length%4)%4)),key=Uint8Array.from(raw,c=>c.charCodeAt(0));let sub=await reg.pushManager.getSubscription();if(sub&&sub.options.applicationServerKey&&String(new Uint8Array(sub.options.applicationServerKey))!==String(key)){await sub.unsubscribe();sub=null;}sub=sub||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await post('/subscribe',{subscription:sub.toJSON()});await post('/push-preferences',{preferences:{enabled:true}});d.querySelector('[name=enabled]').checked=true;status.textContent='Oznámení zapnuta a odběr uložen. Nyní můžeš ověřit doručení testem.';
 });
 d.querySelector('[data-off]').onclick=action(async()=>{const reg=await ready(),sub=await reg.pushManager.getSubscription();if(sub){await post('/unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe();}status.textContent='Oznámení na tomto zařízení vypnuta.';});
 d.querySelector('[data-test]').onclick=action(async()=>{status.textContent=(await post('/push-test')).message;});
 };
 addEventListener('DOMContentLoaded',()=>{const b=document.createElement('button');b.className='btn secondary';b.textContent='Moje oznámení';b.onclick=window.perfectNotificationSettings106;document.querySelector('.top-actions')?.append(b);});
})();

